using namespace std;
using ll = long long;

const ll BASE = 911382323;
const ll MOD = (1LL << 61) - 1; // large prime for multiplication

ll modmul(ll a, ll b) {
    ll res = 0;
    a %= MOD;
    while (b) {
        if (b & 1) res = (res + a) % MOD;
        a = (a * 2) % MOD;
        b >>= 1;
    }
    return res;
}

