#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct Key {
    ll x, y;
    bool operator==(const Key& other) const {
        return x == other.x && y == other.y;
    }
};

struct KeyHash {
    size_t operator()(const Key& k) const {
        auto h1 = std::hash<ll>()(k.x);
        auto h2 = std::hash<ll>()(k.y);
        return h1 * 1000003ULL ^ h2;
    }
};

