#define MOD1 1000000007
#define MOD2 1000000009
#define BASE 91138233

typedef long long ll;

typedef struct {
    int p;
    ll h1, h2;
} State;

State states[200005];
ll pow1[400005], pow2[400005];
int N;
char S[200005];

int main() {
    scanf("%d", &N);
    scanf("%s", S);

    // precompute powers up to 2*N shift (since pointer can go max N in either direction)
    pow1[0] = 1; pow2[0] = 1;
    int maxpow = 2*N + 5;
    for (int i = 1; i <= maxpow; i++) {
        pow1[i] = (pow1[i-1] * BASE) % MOD1;
        pow2[i] = (pow2[i-1] * BASE) % MOD2;
    }

    int p = 0;
    ll h1 = 0, h2 = 0;
    int offset = N; // shift to make index non-negative
    states[0].p = 0; states[0].h1 = 0; states[0].h2 = 0;

    for (int i = 0; i < N; i++) {
        char c = S[i];
        if (c == '+') {
            int idx = p + offset;
            h1 = (h1 + pow1[idx]) % MOD1;
            h2 = (h2 + pow2[idx]) % MOD2;
        } else if (c == '-') {
            int idx = p + offset;
            h1 = (h1 - pow1[idx] + MOD1) % MOD1;
            h2 = (h2 - pow2[idx] + MOD2) % MOD2;
        } else if (c == '>') {
            p++;
        } else if (c == '<') {
            p--;
        }
        states[i+1].p = p;
        states[i+1].h1 = h1;
        states[i+1].h2 = h2;
    }

    int full_p = states[N].p;
    ll full_h1 = states[N].h1;
    ll full_h2 = states[N].h2;

    // Precompute shifted states
    State shifted[200005];
    for (int i = 0; i <= N; i++) {
        int newp = states[i].p + full_p;
        ll newh1 = (states[i].h1 * pow1[full_p + offset] + full_h1) % MOD1;
        ll newh2 = (states[i].h2 * pow2[full_p + offset] + full_h2) % MOD2;
        shifted[i].p = newp;
        shifted[i].h1 = newh1;
        shifted[i].h2 = newh2;
    }

    // Use simple hash map for pairs (h1, h2)
    // Since N <= 200000, we can use a simple array + linked list or use uthash.
    // Let's implement a simple modulo hash table with chaining.
    #define HM_SIZE 300007
    typedef struct Entry {
        ll h1, h2;
        int cnt;
        struct Entry *next;
    } Entry;
    Entry* hm[HM_SIZE];

    auto hash_pair = [](ll h1, ll h2) -> int {
        return ((h1 * 1000003 + h2) % HM_SIZE + HM_SIZE) % HM_SIZE;
    };

    auto add = [&](ll h1, ll h2, int delta) {
        int idx = hash_pair(h1, h2);
        Entry* e = hm[idx];
        while (e) {
            if (e->h1 == h1 && e->h2 == h2) {
                e->cnt += delta;
                return;
            }
            e = e->next;
        }
        // new entry
        Entry* ne = malloc(sizeof(Entry));
        ne->h1 = h1; ne->h2 = h2; ne->cnt = delta; ne->next = hm[idx];
        hm[idx] = ne;
    };

    auto get = [&](ll h1, ll h2) -> int {
        int idx = hash_pair(h1, h2);
        Entry* e = hm[idx];
        while (e) {
            if (e->h1 == h1 && e->h2 == h2) return e->cnt;
            e = e->next;
        }
        return 0;
    };

    ll ans = 0;
    add(shifted[0].h1, shifted[0].h2, 1);
    for (int j = 1; j <= N; j++) {
        ans += get(states[j].h1, states[j].h2);
        add(shifted[j].h1, shifted[j].h2, 1);
    }

    printf("%lld\n", ans);

    // free memory
    for (int i = 0; i < HM_SIZE; i++) {
        Entry* e = hm[i];
        while (e) {
            Entry* tmp = e;
            e = e->next;
            free(tmp);
        }
    }

    return 0;
}

