#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef long long ll;

typedef struct {
    ll x, y;
} Pair;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll*)a;
    ll y = *(const ll*)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

static int cmp_pair(const void *a, const void *b) {
    const Pair *p = (const Pair*)a;
    const Pair *q = (const Pair*)b;
    if (p->x < q->x) return -1;
    if (p->x > q->x) return 1;
    if (p->y < q->y) return -1;
    if (p->y > q->y) return 1;
    return 0;
}

int main(void) {
    int N;
    char *S;

    if (scanf("%d", &N) != 1) return 0;
    S = (char*)malloc((N + 5) * sizeof(char));
    scanf("%s", S + 1);

    int *prefP = (int*)malloc((N + 1) * sizeof(int));
    int *sufMin = (int*)malloc((N + 2) * sizeof(int));
    int *sufMax = (int*)malloc((N + 2) * sizeof(int));

    prefP[0] = 0;
    for (int i = 1; i <= N; i++) {
        prefP[i] = prefP[i - 1];
        if (S[i] == '>') prefP[i]++;
        else if (S[i] == '<') prefP[i]--;
    }

    /* For suffix [i..N], viewed from starting pointer 0:
       positions visited are prefP[k]-prefP[i-1] for k=i-1..N.
       So min/max are derived from prefP on suffix k>=i-1.
    */
    sufMin[N + 1] = prefP[N];
    sufMax[N + 1] = prefP[N];
    for (int t = N; t >= 0; t--) {
        if (t == N) {
            sufMin[t] = prefP[t];
            sufMax[t] = prefP[t];
        } else {
            sufMin[t] = prefP[t] < sufMin[t + 1] ? prefP[t] : sufMin[t + 1];
            sufMax[t] = prefP[t] > sufMax[t + 1] ? prefP[t] : sufMax[t + 1];
        }
    }

    /* Build events for + and -:
       At step k, operation affects position prefP[k-1].
       For substring [i..j] to reproduce whole effect:
       - operations before i and after j must be outside visited interval of [i..j]
       - inside interval, counts must match all operations of S
       This is possible iff [i..j] visits every position ever modified in S,
         and for each modified position, all its +/- occurrences lie within [i..j].
       Since a position's occurrences can be separated in time, this means
         first and last occurrence times of each position must both lie in [i..j].
       Then [i..j] must also end at final pointer prefP[N].

       Let for each position x:
         L[x] = first time k with S[k] in +,- and prefP[k-1]=x
         R[x] = last  time k with S[k] in +,- and prefP[k-1]=x
       Let modified positions be all such x.
       Then valid [i..j]:
         i <= min_x L[x]
         j >= max_x R[x]
         substring path from 0 over S[i..j] visits all modified positions x
         and final displacement equals prefP[N].

       Since every modified x must have all its +/- inside [i..j], necessarily
         i <= global minimum first occurrence among modified positions = Lall
         j >= global maximum last occurrence among modified positions = Rall.
       Conversely that condition already includes all +/- operations.
       Thus substring effect equals whole effect iff pointer trajectory of [i..j]
       covers every modified position.

       The visited positions of [i..j] in global coordinates are:
         prefP[i-1] + { prefP[t]-prefP[i-1] for t=i-1..j }
         = { prefP[t] : t=i-1..j }.
       So it is exactly the set of prefix-pointer values on interval [i-1..j].
       Therefore we need:
         1) j >= Rall, i <= Lall
         2) prefP[j] - prefP[i-1] = prefP[N]
         3) interval [i-1..j] contains at least one occurrence of every modified position,
            which is equivalent to [minMod, maxMod] subset of
            [ min prefP on i-1..j , max prefP on i-1..j ]
            because the walk moves by unit steps.

       Since i <= Lall and j >= Rall, the interval [i-1..j] already contains every
       time a modification happened, hence every modified position is visited there.
       So condition 3 is automatic.

       Thus answer reduces to counting pairs:
         1 <= i <= j <= N
         i <= Lall, j >= Rall
         prefP[j] - prefP[i-1] = prefP[N]
       i.e. prefP[i-1] = prefP[j] - prefP[N].
    */

    int hasMod = 0;
    int Lall = N + 1, Rall = 0;
    for (int k = 1; k <= N; k++) {
        if (S[k] == '+' || S[k] == '-') {
            hasMod = 1;
            if (k < Lall) Lall = k;
            if (k > Rall) Rall = k;
        }
    }

    ll ans = 0;
    if (!hasMod) {
        /* Need only final pointer to match whole string: prefP[j]-prefP[i-1]=prefP[N] */
        Pair *arr = (Pair*)malloc((ll)(N + 1) * sizeof(Pair));
        for (int t = 0; t <= N; t++) {
            arr[t].x = prefP[t];
            arr[t].y = t;
        }
        qsort(arr, N + 1, sizeof(Pair), cmp_pair);

        int l = 0;
        while (l <= N) {
            int r = l;
            while (r + 1 <= N && arr[r + 1].x == arr[l].x) r++;
            ll m = r - l + 1;
            /* count pairs a<b among equal prefP, corresponding to i-1=a, j=b */
            ans += m * (m - 1) / 2;
            l = r + 1;
        }
        free(arr);
    } else {
        /* Count j in [Rall..N], and a=i-1 in [0..Lall-1], with prefP[a]=prefP[j]-prefP[N] */
        ll *leftVals = (ll*)malloc((ll)Lall * sizeof(ll));
        for (int a = 0; a <= Lall - 1; a++) leftVals[a] = prefP[a];
        qsort(leftVals, Lall, sizeof(ll), cmp_ll);

        for (int j = Rall; j <= N; j++) {
            ll target = (ll)prefP[j] - prefP[N];
            ll *lb = (ll*)bsearch(&target, leftVals, Lall, sizeof(ll), cmp_ll);
            if (!lb) continue;
            int pos = (int)(lb - leftVals);
            int L = pos, R = pos;
            while (L - 1 >= 0 && leftVals[L - 1] == target) L--;
            while (R + 1 < Lall && leftVals[R + 1] == target) R++;
            ans += (R - L + 1);
        }
        free(leftVals);
    }

    printf("%lld\n", ans);

    free(prefP);
    free(sufMin);
    free(sufMax);
    free(S);
    return 0;
}

