public class Main {
    // Fast scanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }

    static long pack(int x, int y) {
        return (((long) x) << 32) ^ (y & 0xffffffffL);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        String S = fs.next();
        int N = S.length();
        char[] s = S.toCharArray();

        // Prefix position after first k chars
        int[] pos = new int[N + 1];
        for (int i = 0; i < N; i++) {
            pos[i + 1] = pos[i];
            if (s[i] == '>') pos[i + 1]++;
            else if (s[i] == '<') pos[i + 1]--;
        }

        // Prefix counts of + and - at each absolute position:
        // For each k, define vector F_k[p] = (#plus on p up to k) - (#minus on p up to k)
        // Need pairs (l, r) with l=i-1, r=j such that:
        // 1) pos[r] = pos[l]
