        long final1 = h1[N];
        long final2 = h2[N];

        // Need count of l<r such that H_r - H_l = H_N
        // => H_l = H_r - H_N
        HashMap<Long, Integer> map = new HashMap<>();
        long ans = 0;

        // l can be 0..N-1, r=l+1..N
        // Insert H_0 first
        map.put(pack((int) h1[0], (int) h2[0]), 1);

        for (int r = 1; r <= N; r++) {
            long need1 = h1[r] - final1;
            if (need1 < 0) need1 += MOD1;
            long need2 = h2[r] - final2;
            if (need2 < 0) need2 += MOD2;
            Integer cnt = map.get(pack((int) need1, (int) need2));
            if (cnt != null) ans += cnt;

            long key = pack((int) h1[r], (int) h2[r]);
            map.put(key, map.getOrDefault(key, 0) + 1);
        }

        System.out.println(ans);
    }

    static long modPow(long a, long e, long mod) {
        long r = 1 % mod;
        while (e > 0) {
            if ((e & 1) != 0) r = r * a % mod;
            a = a * a % mod;
            e >>= 1;
        }
        return r;
    }
}
